package kec.allocator;
import java.sql.*; import java.util.*;
public class IncubatorDAO {
 public void saveProposal(StartupProposal p)throws Exception{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{
  int id; try(PreparedStatement q=c.prepareStatement("SELECT startup_id FROM startups WHERE proposal_code=?")){q.setString(1,p.code);try(ResultSet r=q.executeQuery()){if(r.next()){id=r.getInt(1);try(PreparedStatement u=c.prepareStatement("UPDATE startups SET startup_name=?,category=?,business_score=?,prototype_score=?,pitch_score=?,impact_score=?,feasibility_score=? WHERE startup_id=?")){bind(u,p,false);u.setInt(8,id);u.executeUpdate();}}else{try(PreparedStatement i=c.prepareStatement("INSERT INTO startups(proposal_code,startup_name,category,business_score,prototype_score,pitch_score,impact_score,feasibility_score) VALUES(?,?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){bind(i,p,true);i.executeUpdate();try(ResultSet k=i.getGeneratedKeys()){k.next();id=k.getInt(1);}}}}}
  p.id=id; try(PreparedStatement f=c.prepareStatement("INSERT INTO founders(startup_id,student_name,sgpa,backlog_cleared) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE sgpa=VALUES(sgpa),backlog_cleared=VALUES(backlog_cleared)")){for(var x:p.founders){f.setInt(1,id);f.setString(2,x.name());f.setDouble(3,x.sgpa());f.setBoolean(4,x.backlogCleared());f.addBatch();}f.executeBatch();} c.commit();
 }catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
 private void bind(PreparedStatement s,StartupProposal p,boolean insert)throws SQLException{int n=1;if(insert)s.setString(n++,p.code);s.setString(n++,p.name);s.setString(n++,p.category);s.setDouble(n++,p.business);s.setDouble(n++,p.prototype);s.setDouble(n++,p.pitch);s.setDouble(n++,p.impact);s.setDouble(n,p.feasibility);}
 public List<StartupProposal> all()throws Exception{List<StartupProposal> a=new ArrayList<>();Map<Integer,StartupProposal> map=new HashMap<>();try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM startups ORDER BY proposal_code")){while(r.next()){StartupProposal p=new StartupProposal();p.id=r.getInt("startup_id");p.code=r.getString("proposal_code");p.name=r.getString("startup_name");p.category=r.getString("category");p.business=r.getDouble("business_score");p.prototype=r.getDouble("prototype_score");p.pitch=r.getDouble("pitch_score");p.impact=r.getDouble("impact_score");p.feasibility=r.getDouble("feasibility_score");a.add(p);map.put(p.id,p);}}
  try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM founders")){while(r.next()){StartupProposal p=map.get(r.getInt("startup_id"));if(p!=null)p.founders.add(new StartupProposal.Founder(r.getString("student_name"),r.getDouble("sgpa"),r.getBoolean("backlog_cleared")));}}return a;}
 public void saveResult(EvaluationResult r)throws Exception{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("INSERT INTO pitch_scores(startup_id,final_score,category_threshold_met,eligibility_status) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE final_score=VALUES(final_score),category_threshold_met=VALUES(category_threshold_met),eligibility_status=VALUES(eligibility_status),evaluated_at=CURRENT_TIMESTAMP");PreparedStatement g=c.prepareStatement("INSERT INTO grant_allocations(startup_id,grant_amount,grant_tier,approval_status,disbursement_status) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE grant_amount=VALUES(grant_amount),grant_tier=VALUES(grant_tier),approval_status=VALUES(approval_status),disbursement_status=VALUES(disbursement_status)")){p.setInt(1,r.startupId());p.setDouble(2,r.score());p.setBoolean(3,r.thresholdMet());p.setString(4,r.academicEligible()?"ELIGIBLE":"CONDITIONAL");p.executeUpdate();g.setInt(1,r.startupId());g.setDouble(2,r.grant());g.setString(3,r.tier());g.setString(4,r.status());g.setString(5,r.disbursement());g.executeUpdate();c.commit();}catch(Exception e){c.rollback();throw e;}}}
 public List<String[]> results()throws Exception{List<String[]> a=new ArrayList<>();String q="SELECT s.proposal_code,s.startup_name,p.final_score,g.grant_tier,g.grant_amount,g.approval_status,g.disbursement_status FROM startups s JOIN pitch_scores p ON s.startup_id=p.startup_id JOIN grant_allocations g ON s.startup_id=g.startup_id ORDER BY p.final_score DESC";try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next())a.add(new String[]{r.getString(1),r.getString(2),String.format(Locale.US,"%.2f",r.getDouble(3)),r.getString(4),String.format(Locale.US,"%.2f",r.getDouble(5)),r.getString(6),r.getString(7)});}return a;}
 public double ism()throws Exception{try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COALESCE((SELECT SUM(grant_amount) FROM grant_allocations WHERE approval_status='APPROVED'),0),(SELECT COUNT(*) FROM pitch_scores)")){r.next();int n=r.getInt(2);return n==0?0:r.getDouble(1)/n;}}
}
